    for c in s:
        if c == 'L':
            L += 1
        elif c == 'R':
            R += 1
        elif c == 'U':
            U += 1
        else:
            D += 1

    # Tính số bước tối đa có thể giữ lại
    max_steps = min(L, R) + min(U, D)
    return max_steps

