def prime_fib(n: int):
    def is_prime(num):
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    fib = [0, 1]
    while len(fib) < n:
        next_fib = fib[-1] + fib[-2]
        fib.append(next_fib)

    prime_fibs = [fib[i] for i in range(len(fib)) if is_prime(fib[i])]
    return prime_fibs[n - 1]

