def get_neighbourhood(n_type, mat, coordinates):
    if not mat:
        return []
    m, n = len(mat), len(mat[0])
    x, y = coordinates
    if x < 0 or x >= m or y < 0 or y >= n:
        return []

    def get_moore():
        return [
            mat[i][j]
            for i in range(max(0, x - 1), min(m, x + 2))
            for j in range(max(0, y - 1), min(n, y + 2))
            if (i, j) != (x, y)
        ]

    def get_von_neumann():
        return [mat[x + dx][y + dy] for dx, dy in [(0, -1), (-1, 0), (1, 0), (0, 1)]]

    return get_moore() if n_type == "moore" else get_von_neumann()

